import {commuteSnapshot} from './planning-commute-cash-data.js';
export const commuteCashDefinitions={commuteCash:{title:'Build an independent attendance, fare and travel-time scenario',fields:[
 ['commuteDays','On-site days in each included month',12,0,23,1],
 ['commuteMonths','Identical months included in the scenario',12,1,12,1],
 ['commutePass','Monthly transit pass purchased in every included month (CAD)',160,0,400,5],
 ['commuteFare','Pay-per-use transit cash for a complete return commute (CAD)',8,0,30,.5],
 ['commuteCar','Avoidable car cash per complete return commute (CAD)',18,0,100,1],
 ['commuteMinutes','Personal one-way minutes for one chosen route',40,0,120,5]
]}};
export function commuteCashPlan(d){
 const days=d.commuteDays*d.commuteMonths,pass=d.commutePass*d.commuteMonths,fare=days*d.commuteFare,car=days*d.commuteCar,hours=days*d.commuteMinutes*2/60;
 return {days,pass,fare,car,hours,breakEvenDays:d.commuteFare>0?d.commutePass/d.commuteFare:null};
}
export function commuteCashResult(kind,d){
 if(kind!=='commuteCash')throw Error('Unknown commuting cash topic.');
 const p=commuteCashPlan(d);
 return {metrics:[['Pass cash across included months',p.pass,'money'],['Pay-per-use transit cash',p.fare,'money'],['Avoidable car commuting cash',p.car,'money'],['Travel hours for the independently entered route',p.hours,'decimal']],note:'The first two charts retain a fixed May 2025 Statistics Canada snapshot, released 26 August 2025 and reviewed 25 October 2026. The selected main-mode shares and group means do not change with the personal controls. Commuters usually work most hours outside the home; the survey population is ages 15–69 in the provinces, with the source exclusions stated below. The selected shares are not a complete partition and are not renormalized. No confidence intervals or causal estimates are calculated. The last two charts are original hypothetical calculations using independent inputs, not source fare or route estimates. Every included month has the same number of on-site days. A pass is bought in every included month, including one with zero on-site days, and covers every modeled transit trip. Per-use fare is the complete return-trip cash, without fare caps, transfers, concessions or non-work travel. Car cash includes only costs actually avoided when a return commute is not made; purchase cost, financing, retained insurance and other continuing ownership costs are excluded. One independently entered route takes the same time in both directions, including all travel components the reader supplies. Time is not converted into wages or available bank cash. The alternatives are separate scenarios and are not added together. No tax deduction, employer reimbursement, future fare inflation or recommendation of a travel mode is calculated.',charts:[
  {id:'commute-cash-mode-shares',type:'bar',title:'A main-mode share describes commuters, rather than every employed person',unit:'percent',unitLabel:'Selected shares of commuters · Canada, provinces · May 2025',rows:commuteSnapshot.rows.map(r=>({label:r.label,value:r.share/100})),note:'Commuters usually work most hours outside the home. Workers usually spending most work hours at home are excluded from this denominator. Three selected main-mode groups are shown; other methods are omitted, so these bars do not form a complete 100% allocation. These population shares are not an individual’s probability of using a mode.',source:commuteSnapshot.url,sourceLabel:'Statistics Canada · May 2025 · released 26 August 2025'},
  {id:'commute-cash-mode-minutes',type:'bar',title:'A mean trip duration belongs to the group using that main mode',unit:'decimal',unitLabel:'Mean minutes for the trip to work · May 2025 · not a return trip',tableUnit:'Mean one-way minutes',rows:commuteSnapshot.rows.map(r=>({label:r.label,value:r.minutes})),note:'The May 2025 questionnaire CCOMM_Q04 asks about the trip to work. Each bar describes a different group of commuters. These are means, not medians, reliability bounds or matched routes. The gaps do not estimate what would happen if the same person switched modes. The personal time control below does not inherit any of these group means.',source:commuteSnapshot.url,sourceLabel:'Statistics Canada · May 2025 · released 26 August 2025'},
  {id:'commute-cash-attendance-cost',type:'line',title:'A committed monthly pass stays flat while per-use cash changes with attendance',unit:'money',unitLabel:'CAD over the selected number of identical months · separate alternatives',xLabel:'On-site days per month',series:[{name:'Pass bought in each included month',dash:true,rows:Array.from({length:24},(_,x)=>({x,value:d.commuteMonths*d.commutePass}))},{name:'Pay-per-use transit',rows:Array.from({length:24},(_,x)=>({x,value:x*d.commuteMonths*d.commuteFare}))},{name:'Avoidable car commuting cash',rows:Array.from({length:24},(_,x)=>({x,value:x*d.commuteMonths*d.commuteCar}))}],note:'At the entered attendance, compare the metrics above. Pass cash equals per-use transit cash when days per month equal the monthly pass price divided by the complete return fare, if that fare is positive. This crossing may be fractional or outside 0–23 days. The car line excludes continuing ownership costs; it is not a total-cost comparison between owning a car and having no car.'},
  {id:'commute-cash-time-matrix',type:'heatmap',title:'Record travel time separately from the fare comparison',unit:'decimal',unitLabel:'Travel hours across included months · equal outward and return times',tableUnit:'Travel hours',columns:['20 min','35 min','50 min','65 min'],rows:[4,8,12,20].map(days=>({label:days+' days/mo',values:[20,35,50,65].map(minutes=>2*minutes*days*d.commuteMonths/60)})),note:'Columns are independently assumed one-way minutes and rows are on-site days per month. Each cell equals two trips × minutes × on-site days × included months ÷ 60. It does not multiply the survey means or assign a wage to saved time. The entered route time and attendance determine the separate hours metric; neither is a survey estimate.'}
 ]};
}
